 {name="Beneficial Manifestations",source="AitFR-AVT",dice="1d100",rows={
  {min=1,max=20,result="Your creation has a smell that is pleasing to you, even if there is no source for it."},
  {min=21,max=30,result="You can spend 1 minute to dispel any lightly obscuring conditions within 120 feet in your creation."},
  {min=31,max=40,result="Within your creation, you can cast create food and water once per day without using a spell slot."},
  {min=41,max=50,result="You can understand any language spoken within 30 feet of you while within your creation."},
  {min=51,max=60,result="Beasts find your creation appealing or off-putting (you decide)."},
  {min=61,max=70,result="When your creation is made, you decide what weather is possible within it."},
  {min=71,max=80,result="You cannot be charmed or frightened while within your creation."},
  {min=81,max=90,result="All structures in your creation have +2 AC."},
  {min=91,max=100,result="You have advantage on your passive Perception score within your creation."},
 }},
 {name="Damage Types",source="PHB",dice="1d100",rows={
  {min=1,max=1,result="The corrosive spray of a black dragon's breath and the dissolving enzymes secreted by a black pudding deal acid damage."},
  {min=2,max=2,result="Blunt force attacks—hammers, falling, constriction, and the like—deal bludgeoning damage."},
  {min=3,max=3,result="The infernal chill radiating from an ice devil's spear and the frigid blast of a white dragon's breath deal cold damage."},
  {min=4,max=4,result="Red dragons breathe fire, and many spells conjure flames to deal fire damage."},
  {min=5,max=5,result="Force is pure magical energy focused into a damaging form. Most effects that deal force damage are spells, including magic missile and spiritual weapon."},
  {min=6,max=6,result="A lightning bolt spell and a blue dragon's breath deal lightning damage."},
  {min=7,max=7,result="Necrotic damage, dealt by certain undead and some spells, withers matter and even the soul."},
  {min=8,max=8,result="Puncturing and impaling attacks, including spears and monsters' bites, deal piercing damage."},
  {min=9,max=9,result="Venomous stings and the toxic gas of a green dragon's breath deal poison damage."},
  {min=10,max=10,result="Mental abilities such as a mind flayer's psionic blast deal psychic damage."},
  {min=11,max=11,result="Radiant damage, dealt by a cleric's flame strike spell or an angel's smiting weapon, sears the flesh like fire and overloads the spirit with power."},
  {min=12,max=12,result="Swords, axes, and monsters' claws deal slashing damage."},
  {min=13,max=13,result="A concussive burst of sound, such as the effect of the thunderwave spell, deals thunder damage."},
 }},
